fails = []
for f, rules in RULES.items():
    p = D / f
    t = p.read_text(encoding='utf-8')
    print(f'== {f}')
    for old, new, want in rules:
        n = t.count(old)
        if want is None:
            want = n
        mark = 'OK  ' if n == want else 'FAIL'
        if n != want: fails.append(f'{f}: {old[:30]} 命中{n} 期望{want}')
        print(f'  [{mark}] x{n}/{want}  {old[:44]}')
        t = t.replace(old, new)
    p.write_text(t, encoding='utf-8')

# 残留冲突断言：这些串必须一个都不剩
MUST_BE_GONE = ['186亿元','1.2万人','6800人','92亿元','成立于2009年','远航智能成立于2012年','赵启明','陈立恒',
                '陈亦舟','顾承远','何宜宁','深圳市质量检测研究院','深圳市公安局南山分局','19.4亿元',
                '星澜科技成立于 2015 年','远航智能成立于 2013 年']
print('== 残留冲突检查（必须全为 0）')
for f in ['part1.md','part2.md','part3.md']:
    t = (D / f).read_text(encoding='utf-8')
    for s in MUST_BE_GONE:
        c = t.count(s)
        if c:
            print(f'  [FAIL] {f} 残留 {s} x{c}')
            fails.append(f'{f} 残留 {s}')
    print(f'  [OK] {f} 无残留')

if fails:
    print('\n!! 失败项:'); [print('   -', x) for x in fails]; sys.exit(1)
print('\n全部替换命中一致，且无残留冲突')
